#!/usr/bin/env node
// Writes station/hub/src/report/brand-assets.generated.ts, the brand assets the spatial report
// embeds, from the files that are already generated for the phone and the web:
//
// - Inter Regular and SemiBold: the TrueType fonts the phone's plan sheet embeds (PlanExport
//   ChapterBrandAssets.swift, generated by tools/brand/generate_plan_brand.py: static instances
//   at weight 400 and 600, cut down to the WinAnsi characters, no hinting). The report embeds the
//   same bytes, so a name prints with the same glyphs on the sheet and in the report and every
//   WinAnsi letter (Š, ž, Ÿ, ƒ, ...) has its glyph.
// - The Chapter logo: the path data of web/public/brand/chapter-logo.svg (viewBox 0 0 1756 635,
//   y down, as pdfkit's path() reads it).
//
//   node station/hub/scripts/generate-brand-assets.mjs          # writes the file
//   node station/hub/scripts/generate-brand-assets.mjs --check  # exits 1 if it would change
//
// The output depends only on the two inputs; their SHA-256 are written into it.

import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
const FONTS_SOURCE = "ios/Packages/PlanExport/Sources/PlanExport/ChapterBrandAssets.swift";
const LOGO_SOURCE = "web/public/brand/chapter-logo.svg";
const OUTPUT = "station/hub/src/report/brand-assets.generated.ts";

function sha256(data) {
  return createHash("sha256").update(data).digest("hex");
}

/** The base64 TrueType data of one EmbeddedFont in ChapterBrandAssets.swift. */
function fontBase64(swift, name) {
  const start = swift.indexOf(`static let ${name} = EmbeddedFont(`);
  if (start === -1) {
    throw new Error(`${FONTS_SOURCE} has no font ${name}`);
  }
  const open = swift.indexOf('base64: """', start);
  const close = swift.indexOf('"""', open + 'base64: """'.length);
  if (open === -1 || close === -1) {
    throw new Error(`${FONTS_SOURCE}: no base64 block for ${name}`);
  }
  const text = swift.slice(open + 'base64: """'.length, close).replace(/\s+/g, "");
  const bytes = Buffer.from(text, "base64");
  // A TrueType font starts with version 0x00010000.
  if (bytes.readUInt32BE(0) !== 0x00010000) {
    throw new Error(`${FONTS_SOURCE}: ${name} is not a TrueType font`);
  }
  return text;
}

function logo(svg) {
  const viewBox = /viewBox="0 0 (\d+(?:\.\d+)?) (\d+(?:\.\d+)?)"/.exec(svg);
  if (viewBox === null) {
    throw new Error(`${LOGO_SOURCE} has no viewBox`);
  }
  const paths = [...svg.matchAll(/<path\b[^>]*\sd="([^"]+)"/g)].map((match) => match[1]);
  if (paths.length === 0) {
    throw new Error(`${LOGO_SOURCE} has no paths`);
  }
  return { width: Number(viewBox[1]), height: Number(viewBox[2]), paths };
}

function wrap(text, width) {
  const lines = [];
  for (let i = 0; i < text.length; i += width) {
    lines.push(text.slice(i, i + width));
  }
  return lines;
}

function render() {
  const swiftBytes = readFileSync(resolve(root, FONTS_SOURCE));
  const svgBytes = readFileSync(resolve(root, LOGO_SOURCE));
  const swift = swiftBytes.toString("utf8");
  const regular = fontBase64(swift, "interRegular");
  const semibold = fontBase64(swift, "interSemiBold");
  const mark = logo(svgBytes.toString("utf8"));
  const stringArray = (text) =>
    wrap(text, 96)
      .map((line) => `  "${line}",`)
      .join("\n");
  return `// Generated by station/hub/scripts/generate-brand-assets.mjs. Do not edit.
//
// Inter (SIL Open Font License 1.1, see station/hub/THIRD_PARTY_NOTICES.md) as the phone's plan
// sheet embeds it, and the Chapter logo (a Chapter trademark).
// Sources: ${FONTS_SOURCE} (sha256 ${sha256(swiftBytes)})
//          ${LOGO_SOURCE} (sha256 ${sha256(svgBytes)})

/** Inter Regular, TrueType, WinAnsi characters only (base64 in parts). */
export const INTER_REGULAR_TTF_BASE64: readonly string[] = [
${stringArray(regular)}
];

/** Inter SemiBold, TrueType, WinAnsi characters only (base64 in parts). */
export const INTER_SEMIBOLD_TTF_BASE64: readonly string[] = [
${stringArray(semibold)}
];

/** Size of the logo's view box, logo units. */
export const LOGO_WIDTH = ${mark.width};
export const LOGO_HEIGHT = ${mark.height};

/** The logo ("chapter" over "RENOVATION") as SVG path data, y down, filled nonzero. */
export const LOGO_PATHS: readonly string[] = [
${mark.paths.map((d) => `  ${JSON.stringify(d)},`).join("\n")}
];
`;
}

const output = render();
const target = resolve(root, OUTPUT);
if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(target, "utf8");
  } catch {
    // Missing counts as different.
  }
  if (current !== output) {
    process.stderr.write(
      `${OUTPUT} is out of date: run node station/hub/scripts/generate-brand-assets.mjs\n`,
    );
    process.exit(1);
  }
  process.stdout.write(`${OUTPUT} is up to date\n`);
} else {
  writeFileSync(target, output);
  process.stdout.write(`wrote ${OUTPUT}\n`);
}
